    <div style="text-align:center"><div style="border-top:1px solid #d1d5db;padding-top:8px;margin-top:48px"><div style="font-size:12px;color:#6b7280">${n("pdf_recv_sig")}</div><div style="font-size:12px;color:#6b7280;margin-top:2px">${e.contact_name||""}</div></div></div>
